-- Virtual Table Definitions --


-- Access lnav's environment variables through this table.
CREATE TABLE lnav_db.environ (
    name TEXT PRIMARY KEY,
    value TEXT
);

-- Access app files in the lnav configuration directories
CREATE TABLE lnav_db.lnav_app_files (
    name TEXT PRIMARY KEY,
    app TEXT,
    filepath TEXT,
    content BLOB HIDDEN
);

CREATE TABLE lnav_db.lnav_apps (
    name TEXT PRIMARY KEY,
    description TEXT,
    root TEXT
);

CREATE TABLE lnav_db.all_thread_ids (
    thread_id TEXT PRIMARY KEY,  -- The thread ID
    earliest DATETIME,           -- The earliest time this ID was seen
    latest DATETIME,             -- The latest time this ID was seen
    duration INTEGER,            -- The amount of time between earliest and latest in microseconds
    errors INTEGER,              -- The number of error messages associated with this ID
    warnings INTEGER,            -- The number of warning messages associated with this ID
    total INTEGER                -- The total number of messages associated with this ID
);

-- Access statistics for filters through this table.
CREATE TABLE lnav_db.lnav_view_filter_stats (
    view_name TEXT,     -- The name of the view.
    filter_id INTEGER,  -- The filter identifier.
    hits      INTEGER   -- The number of lines that matched this filter.
);

-- Access lnav's log breakpoints through this table.
CREATE TABLE lnav_db.lnav_log_breakpoints (
    schema_id TEXT NOT NULL,                    -- The schema identifier for the breakpoint.  Matches the log_msg_schema in the all_logs table.
    description TEXT NOT NULL,                  -- A human-readable description of the breakpoint (e.g. format:file:line).
    type TEXT NOT NULL DEFAULT 'src_location',  -- The source of the schema ID, either 'src_location' or 'message_schema'.
    enabled INTEGER NOT NULL DEFAULT 1          -- Indicates whether the breakpoint is active.
);

-- Access lnav's views through this table.
CREATE TABLE lnav_db.lnav_views (
    name TEXT PRIMARY KEY,  -- The name of the view.
    top INTEGER,            -- The number of the line at the top of the view, starting from zero.
    left INTEGER,           -- The left position of the viewport.
    height INTEGER,         -- The height of the viewport.
    inner_height INTEGER,   -- The number of lines in the view.
    top_time DATETIME,      -- The time of the top line in the view, if the content is time-based.
    top_file TEXT,          -- The file the top line is from.
    paused INTEGER,         -- Indicates if the view is paused and will not load new data.
    search TEXT,            -- The text to search for in the view.
    filtering INTEGER,      -- Indicates if the view is applying filters.
    movement TEXT,          -- The movement mode, either 'top' or 'cursor'.
    top_meta TEXT,          -- A JSON object that contains metadata related to the top line in the view.
    selection INTEGER,      -- The number of the line that is focused for selection.
    options TEXT,           -- A JSON object that contains optional settings for this view.
    selected_text TEXT,     -- A JSON object that contains information about the text selected by the mouse in the view.
    row_details TEXT        -- A JSON object that contains information about the focused row.
);

--
CREATE TABLE lnav_db.lnav_view_files (
    view_name TEXT,     -- The name of the view.
    filepath  TEXT,     -- The path to the file.
    visible   INTEGER   -- Indicates whether or not the file is shown.
);

-- Access lnav's view stack through this table.
CREATE TABLE lnav_db.lnav_view_stack (
    name TEXT
);

-- Access lnav's filters through this table.
CREATE TABLE lnav_db.lnav_view_filters (
    view_name TEXT,                    -- The name of the view.
    filter_id INTEGER DEFAULT 0,       -- The filter identifier.
    enabled   INTEGER DEFAULT 1,       -- Indicates if the filter is enabled/disabled.
    type      TEXT    DEFAULT 'out',   -- The type of filter (i.e. in/out).
    language  TEXT    DEFAULT 'regex', -- The filter language.
    pattern   TEXT                     -- The filter pattern.
);

CREATE TABLE lnav_db.all_opids (
    opid TEXT PRIMARY KEY,  -- The operation ID
    earliest DATETIME,      -- The earliest time this ID was seen
    latest DATETIME,        -- The latest time this ID was seen
    duration INTEGER,       -- The amount of time between earliest and latest in microseconds
    errors INTEGER,         -- The number of error messages associated with this ID
    warnings INTEGER,       -- The number of warning messages associated with this ID
    total INTEGER,          -- The total number of messages associated with this ID
    definition TEXT,        -- The name of the opid description from the log format, if available
    description TEXT        -- A description of the operation
);

-- Access lnav's open file list through this table.
CREATE TABLE lnav_db.lnav_file (
    device integer,       -- The device the file is stored on.
    inode integer,        -- The inode for the file on the device.
    filepath text,        -- The path to the file.
    mimetype text,        -- The MIME type for the file.
    content_id text,      -- The hash of some unique content in the file.
    format text,          -- The log file format for the file.
    lines integer,        -- The number of lines in the file.
    time_offset integer,  -- The millisecond offset for timestamps.
    options_path TEXT,    -- The matched path for the file options.
    options TEXT,         -- The effective options for the file.

    content BLOB HIDDEN   -- The contents of the file.
);

-- Access the metadata embedded in open files
CREATE TABLE lnav_db.lnav_file_metadata (
    filepath text,    -- The path to the file.
    descriptor text,  -- The descriptor that identifies the source of the metadata.
    mimetype text,    -- The MIME type of the metadata.
    content text      -- The metadata itself.
);

-- The regexp_capture() table-valued function allows you to execute a regular-
-- expression over a given string and get the captured data as rows in a table.
CREATE TABLE regexp_capture (
    match_index INTEGER,
    capture_index INTEGER,
    capture_name TEXT,
    capture_count INTEGER,
    range_start INTEGER,
    range_stop INTEGER,
    content TEXT,
    value TEXT HIDDEN,
    pattern TEXT HIDDEN
);

-- The regexp_capture_into_json() table-valued function allows you to execute a
-- regular-expression over a given string and get the captured data as rows in
-- a table.
CREATE TABLE regexp_capture_into_json (
    match_index INTEGER,
    content TEXT,
    value TEXT HIDDEN,
    pattern TEXT HIDDEN,
    flags TEXT HIDDEN
);

-- The xpath() table-valued function allows you to execute an xpath expression
CREATE TABLE xpath (
    result text,        -- The result of the xpath expression
    node_path text,     -- The absolute path to the node selected by the expression
    node_attr text,     -- The node attributes stored in a JSON object
    node_text text,     -- The text portion of the node selected by the expression

    xpath text HIDDEN,
    value text HIDDEN
);

-- The fstat() table-valued function allows you to query the file system.
CREATE TABLE lnav_db.fstat (
    st_parent TEXT,
    st_name TEXT,
    st_dev INTEGER,
    st_ino INTEGER,
    st_type TEXT,
    st_mode INTEGER,
    st_nlink INTEGER,
    st_uid TEXT,
    st_user TEXT,
    st_gid TEXT,
    st_group TEXT,
    st_rdev INTEGER,
    st_size INTEGER,
    st_blksize INTEGER,
    st_blocks INTEGER,
    st_atime DATETIME,
    st_mtime DATETIME,
    st_ctime DATETIME,
    error TEXT,
    pattern TEXT HIDDEN,
    data BLOB HIDDEN
);

CREATE TABLE lnav_db.access_log  (
  log_line        INTEGER,                         -- The line number for the log message
  log_time        DATETIME,                        -- The adjusted timestamp for the log message
  log_level       TEXT     COLLATE loglevel,       -- The log message level
  -- BEGIN Format-specific fields:
  c_ip            TEXT     COLLATE 'ipaddress'    , -- The client IP address
  cs_method       TEXT     COLLATE 'BINARY'       , -- The request method
  cs_referer      TEXT     COLLATE 'BINARY'       , -- The client's referrer
  cs_uri_query    TEXT     COLLATE 'BINARY'       , -- The query parameters in the request URI
  cs_uri_stem     TEXT     COLLATE 'BINARY'       , -- The path part of the request URI
  cs_user_agent   TEXT     COLLATE 'BINARY'       , -- The client's HTTP agent
  cs_username     TEXT     COLLATE 'BINARY'       , -- The username passed from the client to the server
  cs_version      TEXT     COLLATE 'BINARY'       , -- The client's HTTP version
  sc_bytes        INTEGER  COLLATE 'BINARY'       , -- The number of bytes returned by the server
  sc_status       INTEGER  COLLATE 'BINARY'       , -- The status code returned by the server
  cs_host         TEXT     COLLATE 'BINARY'       , -- The value of the Host header

  -- END Format-specific fields
  log_part         TEXT     COLLATE naturalnocase,    -- The partition the message is in
  log_actual_time  DATETIME HIDDEN,                   -- The timestamp from the original log file for this message
  log_idle_msecs   INTEGER,                           -- The difference in time between this messages and the previous
  log_mark         BOOLEAN,                           -- True if the log message was marked
  log_sticky_mark  BOOLEAN HIDDEN,                    -- True if the log message is a sticky header
  log_comment      TEXT,                              -- The comment for this message
  log_tags         TEXT,                              -- A JSON list of tags for this message
  log_annotations  TEXT,                              -- A JSON object of annotations for this messages
  log_filters      TEXT,                              -- A JSON list of filter IDs that matched this message
  log_opid         TEXT HIDDEN,                       -- The message's OPID from the log message or user
  log_user_opid    TEXT HIDDEN,                       -- The message's OPID as set by the user
  log_opid_definition TEXT HIDDEN,                    -- The matching OPID description definition
  log_format       TEXT HIDDEN,                       -- The name of the log file format
  log_format_regex TEXT HIDDEN,                       -- The name of the regex used to parse this log message
  log_time_msecs   INTEGER HIDDEN,                    -- The adjusted timestamp for the log message as the number of milliseconds from the epoch
  log_path         TEXT HIDDEN COLLATE naturalnocase, -- The path to the log file this message is from
  log_unique_path  TEXT HIDDEN COLLATE naturalnocase, -- The unique portion of the path this message is from
  log_text         TEXT HIDDEN,                       -- The full text of the log message
  log_body         TEXT HIDDEN,                       -- The body of the log message
  log_raw_text     TEXT HIDDEN,                       -- The raw text from the log file
  log_line_hash    TEXT HIDDEN,                       -- A hash of the first line of the log message
  log_line_link    TEXT HIDDEN,                       -- The permalink for the log message
  log_src_file     TEXT HIDDEN,                       -- The source file the log message came from
  log_src_line     TEXT HIDDEN,                       -- The source line the log message came from
  log_thread_id    TEXT HIDDEN,                       -- The ID of the thread that generated this message
  log_duration     REAL HIDDEN                        -- The duration associated with this log message
, PRIMARY KEY (log_line)
);

CREATE TABLE lnav_db.alb_log  (
  log_line        INTEGER,                         -- The line number for the log message
  log_time        DATETIME,                        -- The adjusted timestamp for the log message
  log_level       TEXT     COLLATE loglevel,       -- The log message level
  -- BEGIN Format-specific fields:
  chosen_cert_arn          TEXT     COLLATE 'BINARY'       ,
  client_ip                TEXT     COLLATE 'ipaddress'    ,
  client_port              INTEGER  COLLATE 'BINARY'       ,
  cs_method                TEXT     COLLATE 'BINARY'       ,
  cs_uri_query             TEXT     COLLATE 'BINARY'       ,
  cs_uri_stem              TEXT     COLLATE 'BINARY'       ,
  cs_version               TEXT     COLLATE 'BINARY'       ,
  domain_name              TEXT     COLLATE 'BINARY'       ,
  elb                      TEXT     COLLATE 'BINARY'       ,
  elb_status_code          INTEGER  COLLATE 'BINARY'       ,
  matched_rule_priority    INTEGER  COLLATE 'BINARY'       ,
  received_bytes           INTEGER  COLLATE 'BINARY'       ,
  request_processing_time  FLOAT    COLLATE 'BINARY'       ,
  response_processing_time FLOAT    COLLATE 'BINARY'       ,
  sent_bytes               INTEGER  COLLATE 'BINARY'       ,
  ssl_cipher               TEXT     COLLATE 'BINARY'       ,
  ssl_protocol             TEXT     COLLATE 'BINARY'       ,
  target_group_arn         TEXT     COLLATE 'BINARY'       ,
  target_ip                TEXT     COLLATE 'ipaddress'    ,
  target_port              INTEGER  COLLATE 'BINARY'       ,
  target_processing_time   FLOAT    COLLATE 'BINARY'       ,
  target_status_code       INTEGER  COLLATE 'BINARY'       ,
  trace_id                 TEXT     COLLATE 'BINARY'       ,
  type                     TEXT     COLLATE 'BINARY'       ,
  user_agent               TEXT     COLLATE 'BINARY'       ,

  -- END Format-specific fields
  log_part         TEXT     COLLATE naturalnocase,    -- The partition the message is in
  log_actual_time  DATETIME HIDDEN,                   -- The timestamp from the original log file for this message
  log_idle_msecs   INTEGER,                           -- The difference in time between this messages and the previous
  log_mark         BOOLEAN,                           -- True if the log message was marked
  log_sticky_mark  BOOLEAN HIDDEN,                    -- True if the log message is a sticky header
  log_comment      TEXT,                              -- The comment for this message
  log_tags         TEXT,                              -- A JSON list of tags for this message
  log_annotations  TEXT,                              -- A JSON object of annotations for this messages
  log_filters      TEXT,                              -- A JSON list of filter IDs that matched this message
  log_opid         TEXT HIDDEN,                       -- The message's OPID from the log message or user
  log_user_opid    TEXT HIDDEN,                       -- The message's OPID as set by the user
  log_opid_definition TEXT HIDDEN,                    -- The matching OPID description definition
  log_format       TEXT HIDDEN,                       -- The name of the log file format
  log_format_regex TEXT HIDDEN,                       -- The name of the regex used to parse this log message
  log_time_msecs   INTEGER HIDDEN,                    -- The adjusted timestamp for the log message as the number of milliseconds from the epoch
