  line_number     INTEGER  COLLATE 'BINARY'       ,
  logger          TEXT     COLLATE 'BINARY'       ,
  myid            INTEGER  COLLATE 'BINARY'       ,
  thread          TEXT     COLLATE 'BINARY'       ,

  -- END Format-specific fields
  log_part         TEXT     COLLATE naturalnocase,    -- The partition the message is in
  log_actual_time  DATETIME HIDDEN,                   -- The timestamp from the original log file for this message
  log_idle_msecs   INTEGER,                           -- The difference in time between this messages and the previous
  log_mark         BOOLEAN,                           -- True if the log message was marked
  log_sticky_mark  BOOLEAN HIDDEN,                    -- True if the log message is a sticky header
  log_comment      TEXT,                              -- The comment for this message
  log_tags         TEXT,                              -- A JSON list of tags for this message
  log_annotations  TEXT,                              -- A JSON object of annotations for this messages
  log_filters      TEXT,                              -- A JSON list of filter IDs that matched this message
  log_opid         TEXT HIDDEN,                       -- The message's OPID from the log message or user
  log_user_opid    TEXT HIDDEN,                       -- The message's OPID as set by the user
  log_opid_definition TEXT HIDDEN,                    -- The matching OPID description definition
  log_format       TEXT HIDDEN,                       -- The name of the log file format
  log_format_regex TEXT HIDDEN,                       -- The name of the regex used to parse this log message
  log_time_msecs   INTEGER HIDDEN,                    -- The adjusted timestamp for the log message as the number of milliseconds from the epoch
  log_path         TEXT HIDDEN COLLATE naturalnocase, -- The path to the log file this message is from
  log_unique_path  TEXT HIDDEN COLLATE naturalnocase, -- The unique portion of the path this message is from
  log_text         TEXT HIDDEN,                       -- The full text of the log message
  log_body         TEXT HIDDEN,                       -- The body of the log message
  log_raw_text     TEXT HIDDEN,                       -- The raw text from the log file
  log_line_hash    TEXT HIDDEN,                       -- A hash of the first line of the log message
  log_line_link    TEXT HIDDEN,                       -- The permalink for the log message
  log_src_file     TEXT HIDDEN,                       -- The source file the log message came from
  log_src_line     TEXT HIDDEN,                       -- The source line the log message came from
  log_thread_id    TEXT HIDDEN,                       -- The ID of the thread that generated this message
  log_duration     REAL HIDDEN                        -- The duration associated with this log message
, PRIMARY KEY (log_line)
);

@dataclass
class State:
    all_entries: list[Entry]
    visible_entries: list[Entry]
    plain_lines: list[PlainLine]
    current_index: int = 0
    last_query: QueryResult | None = None
    explicit_output: str | None = None
    had_command_error: bool = False
    active_filter_ids: list[int] | None = None

    def __post_init__(self) -> None:
        if self.active_filter_ids is None:
            self.active_filter_ids = []


def main(argv: Sequence[str]) -> int:
    try:
        opts = parse_args(argv)
    except ParseError as exc:
        print_parse_error(exc)
        return exc.code

    binary_path = str(Path(argv[0]).resolve())
    config_dir = str(Path.home() / ".lnav")
    work_dir = f"/tmp/lnav-user-{os.getuid()}-work"

    if opts.help:
        sys.stderr.write(
            HELP_TEMPLATE.format(
                argv0=argv[0],
                binary_path=binary_path,
                config_dir=config_dir,
                work_dir=work_dir,
            )
        )
        return 0

    if opts.version and not opts.internal_help:
        sys.stdout.write(f"{VERSION}\n")
        return 0

    if opts.update_formats:
        sys.stdout.write(
            "No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n"
        )
        return 0

    if opts.check_config:
        return 0

    if opts.management_mode:
        if not opts.paths:
            sys.stderr.write(MANAGEMENT_HELP)
            return 1
        sys.stderr.write(MANAGEMENT_HELP)
        return 1

    if opts.install_arg is not None:
        return handle_install(opts.install_arg)

    if opts.internal_help:
        if not opts.headless and not sys.stdout.isatty():
            print_ui_error()
            return 1
        sys.stdout.write(load_internal_help())
        return 0

    if opts.debug_file:
        try:
            Path(opts.debug_file).write_text("", encoding="utf-8")
        except OSError:
            pass

    try:
        since_dt = parse_cutoff(opts.since_text, "since") if opts.since_text else None
        until_dt = parse_cutoff(opts.until_text, "until") if opts.until_text else None
    except RuntimeCliError as exc:
        print_runtime_error(exc)
        return exc.code

    runtime = RuntimeContext(
        argv0=argv[0],
        opts=opts,
        since_dt=since_dt,
        until_dt=until_dt,
    )

    try:
        state = runtime.load_state()
    except RuntimeCliError as exc:
        print_runtime_error(exc)
        return exc.code

    if not opts.headless and not sys.stdout.isatty():
        for line in runtime.deferred_errors:
            sys.stderr.write(f"{line}\n")
        print_ui_error()
        return 1

    for line in runtime.deferred_errors:
        sys.stderr.write(f"{line}\n")
        if not line.endswith("\n"):
            pass

    try:
        execute_commands(runtime, state)
    except RuntimeCliError as exc:
        print_runtime_error(exc)
        return exc.code

    if state.explicit_output is not None:
        sys.stdout.write(state.explicit_output)
        return 0

    if state.last_query is not None and not state.had_command_error:
        sys.stdout.write(format_table(state.last_query))
        return 0

    if state.had_command_error:
        return 0

    if opts.quiet:
        return 0

    if state.visible_entries:
        sys.stdout.write(render_log_lines(state.visible_entries))
    elif state.plain_lines:
        sys.stdout.write(render_plain_lines(state.plain_lines))
    return 0


class RuntimeContext:
    def __init__(
        self,
        *,
        argv0: str,
        opts: Options,
        since_dt: datetime | None,
        until_dt: datetime | None,
    ) -> None:
        self.argv0 = argv0
        self.opts = opts
        self.since_dt = since_dt
        self.until_dt = until_dt
        self.deferred_errors: list[str] = []

    def load_state(self) -> State:
        sources: list[Source] = []

        for path in self.expand_paths(self.opts.paths):
            if path == "-":
                sources.append(self.load_stdin_explicit())
                continue
            source = self.load_path(path)
            if source is not None:
                sources.append(source)

        for shell_command in self.opts.shell_commands:
            sources.append(self.load_shell_output(shell_command))

        if self.opts.prepend_stdin_timestamps and "-" not in self.opts.paths and not self.opts.no_default:
            if not sys.stdin.isatty():
                sources.append(self.load_stdin_implicit())

        if not sources:
            default_source = self.load_default_source()
            if default_source is not None:
                sources.append(default_source)

        if not sources:
            if self.opts.no_default:
                return State(all_entries=[], visible_entries=[], plain_lines=[])
            raise RuntimeCliError(
                1,
                [
                    "  error: nothing to do",
                    " reason: no files given or default files found",
                    " = help: use the “-N” option to open lnav without loading any files",
                ],
            )

        log_sources = [src for src in sources if src.log_entries]
        plain_sources = [src for src in sources if src.plain_lines and not src.log_entries]

        if log_sources:
            entries: list[Entry] = []
            out_of_range_errors: list[list[str]] = []
            for src in log_sources:
                filtered = self.apply_time_cutoffs(src)
                if filtered is None:
                    out_of_range_errors.append(self.build_out_of_range_error(src))
                    continue
                entries.extend(filtered)

            if out_of_range_errors:
                raise RuntimeCliError(1, [line for block in out_of_range_errors for line in block])

            entries.sort(key=lambda entry: (entry.log_time, entry.path, entry.log_line))
            for idx, entry in enumerate(entries):
                idle = 0 if idx == 0 else int((entry.log_time - entries[idx - 1].log_time).total_seconds() * 1000)
                entry.log_idle_msecs = idle
                entry.log_line = idx
            return State(all_entries=list(entries), visible_entries=list(entries), plain_lines=[])

        plain_lines: list[PlainLine] = []
        for src in plain_sources:
            plain_lines.extend(src.plain_lines)
        return State(all_entries=[], visible_entries=[], plain_lines=plain_lines)

    def expand_paths(self, paths: Sequence[str]) -> list[str]:
        expanded: list[str] = []
        for path in paths:
            expanded.append(path)
        return expanded

    def load_default_source(self) -> Source | None:
        if self.opts.no_default:
            return None
        for path in ("/var/log/messages", "/var/log/syslog"):
            if Path(path).exists():
                return self.load_path(path)
        return None

    def load_path(self, path: str) -> Source | None:
        target = Path(path)
        if not target.exists():
            self.deferred_errors.extend(
                [
                    f"  error: unable to open file: {path}",
                    " reason: No such file or directory",
                ]
            )
            return None

        if target.is_dir():
            return self.load_directory(target)

        return self.load_file(target, display_path=path)

    def load_directory(self, directory: Path) -> Source:
        if self.opts.recursive:
            files = sorted([p for p in directory.rglob("*") if p.is_file()], key=lambda p: str(p))
        else:
            files = sorted([p for p in directory.iterdir() if p.is_file()], key=lambda p: str(p))

        sources = [self.load_file(path, display_path=str(path)) for path in files]
        log_entries = [entry for src in sources if src is not None for entry in src.log_entries]
        plain_lines = [line for src in sources if src is not None for line in src.plain_lines]

        if log_entries:
            return Source(display_path=str(directory), kind="directory", log_entries=log_entries, plain_lines=[])
        return Source(display_path=str(directory), kind="directory", log_entries=[], plain_lines=plain_lines)

    def load_file(self, path: Path, *, display_path: str) -> Source:
        text = read_text_file(path)
        lines = text.splitlines()
        mtime = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).astimezone().replace(tzinfo=None)
        parsed = [parse_line(line) for line in lines]
        if any(entry is not None for entry in parsed):
            entries: list[Entry] = []
            for idx, parsed_entry in enumerate(parsed):
                if parsed_entry is None:
                    continue
                stamp, body = parsed_entry
                entries.append(
                    Entry(
                        log_line=idx,
                        log_time=stamp,
                        raw_line=lines[idx],
                        body=body,
                        level=detect_level(body),
                        path=str(path.resolve()),
                        log_idle_msecs=0,
                    )
                )
            return Source(display_path=display_path, kind="file", log_entries=entries, plain_lines=[], file_mtime=mtime)

        plain_lines = [PlainLine(raw_line=line, path=str(path.resolve()), line_no=i) for i, line in enumerate(lines)]
        return Source(display_path=display_path, kind="file", log_entries=[], plain_lines=plain_lines, file_mtime=mtime)

    def load_shell_output(self, command: str) -> Source:
        proc = subprocess.run(
            command,
            shell=True,
            text=True,
            capture_output=True,
            check=False,
        )
        text = proc.stdout
        lines = text.splitlines()
        parsed = [parse_line(line) for line in lines]
        if any(entry is not None for entry in parsed):
            entries = []
            for idx, parsed_entry in enumerate(parsed):
                if parsed_entry is None:
                    continue
                stamp, body = parsed_entry
                entries.append(

                entries.append(
                    Entry(
                        log_line=idx,
                        log_time=stamp,
                        raw_line=lines[idx],
                        body=body,
                        level=detect_level(body),
                        path="<shell>",
                        log_idle_msecs=0,
                    )
                )
            return Source(display_path="<shell>", kind="shell", log_entries=entries, plain_lines=[])

        plain_lines = [PlainLine(raw_line=line, path="<shell>", line_no=i) for i, line in enumerate(lines)]
        return Source(display_path="<shell>", kind="shell", log_entries=[], plain_lines=plain_lines)

    def load_stdin_explicit(self) -> Source:
        return self._load_stdin_source(explicit=True)

    def load_stdin_implicit(self) -> Source:
        return self._load_stdin_source(explicit=False)

    def _load_stdin_source(self, *, explicit: bool) -> Source:
        data = sys.stdin.read()
        lines = data.splitlines()
        if self.opts.prepend_stdin_timestamps:
            rendered_lines = [ensure_timestamp(line) for line in lines]
        else:
            rendered_lines = lines

        parsed = [parse_line(line) for line in rendered_lines]
        if any(entry is not None for entry in parsed):
            entries = []
            for idx, parsed_entry in enumerate(parsed):
                if parsed_entry is None:
                    continue
                stamp, body = parsed_entry
                entries.append(
                    Entry(
                        log_line=idx,
                        log_time=stamp,
                        raw_line=rendered_lines[idx],
                        body=body,
                        level=detect_level(body),
                        path="-",
                        log_idle_msecs=0,
                    )
                )
            return Source(display_path="-", kind="stdin", log_entries=entries, plain_lines=[])

        plain_lines = [PlainLine(raw_line=line, path="-", line_no=i) for i, line in enumerate(rendered_lines)]
        return Source(display_path="-", kind="stdin", log_entries=[], plain_lines=plain_lines)

    def apply_time_cutoffs(self, source: Source) -> list[Entry] | None:
        if not source.log_entries or (self.since_dt is None and self.until_dt is None):
            return list(source.log_entries)

        filtered = [
            entry
            for entry in source.log_entries
            if (self.since_dt is None or entry.log_time >= self.since_dt)
            and (self.until_dt is None or entry.log_time <= self.until_dt)
        ]
        if filtered:
            return filtered
        if source.kind != "file":
            return []
        return None

    def build_out_of_range_error(self, source: Source) -> list[str]:
        assert source.file_mtime is not None
        lines = [
            f"  error: unable to open file: {Path(source.display_path).resolve()}",
            f" reason: file contents are out-of-range of time cutoffs “{Path(source.display_path).resolve()}”",
        ]
        file_time = format_sql_time(source.file_mtime)
        lines.append(f" |        = note: File time range is “{file_time}” to “{file_time}”")
        if self.since_dt is not None:
            lines.append(f" |        = note: Minimum time cutoff is “{format_sql_time(self.since_dt)}”")
        if self.until_dt is not None:
            lines.append(f" |        = note: Maximum time cutoff is “{format_sql_time(self.until_dt)}”")
        return lines


def parse_args(argv: Sequence[str]) -> Options:
    opts = Options()
    args = list(argv[1:])
    idx = 0
    while idx < len(args):
        arg = args[idx]

        if arg == "--help":
            opts.help = True
        elif arg == "-h":
            opts.help = True
        elif arg == "-H":
            opts.internal_help = True
        elif arg == "-V":
            opts.version = True
        elif arg == "-u":
            opts.update_formats = True
        elif arg == "-r":
            opts.recursive = True
        elif arg == "-R":
            opts.load_rotated = True
        elif arg == "-n":
            opts.headless = True
        elif arg == "-N":
            opts.no_default = True
        elif arg == "-q":
            opts.quiet = True
        elif arg == "-t":
            opts.prepend_stdin_timestamps = True
        elif arg == "-C":
            opts.check_config = True
        elif arg == "-W":
            pass
        elif arg == "-m":
            opts.management_mode = True
        elif arg in ("-S", "--since"):
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "--since: 1 required TEXT missing")
            opts.since_text = args[idx]
        elif arg in ("-U", "--until"):
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "--until: 1 required TEXT missing")
            opts.until_text = args[idx]
        elif arg == "-d":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-d: 1 required FILE missing")
            opts.debug_file = args[idx]
        elif arg == "-I":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-I: 1 required TEXT:DIR missing")
            opts.extra_config_dirs.append(args[idx])
        elif arg == "-c":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-c: 1 required  missing")
            opts.command_options.append(args[idx])
        elif arg == "-f":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-f: 1 required  missing")
            opts.command_files.append(args[idx])
        elif arg == "-e":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-e: 1 required  missing")
            opts.shell_commands.append(args[idx])
        elif arg == "-i":
            idx += 1
            if idx >= len(args):
                raise ParseError(107, "invalid command-line arguments", "-i requires file")
            opts.install_arg = args[idx]
        elif arg.startswith("-"):
            remainder = " ".join(args[idx:])
            if " " in remainder:
                reason = f"The following arguments were not expected: {remainder}"
            else:
                reason = f"The following argument was not expected: {arg}"
            raise ParseError(109, "invalid command-line arguments", reason)
        else:
            opts.paths.append(arg)
        idx += 1

    if opts.management_mode and (opts.headless or opts.no_default):
        unexpected = []
        if opts.no_default:
            unexpected.append("-N")
        if opts.headless:
            unexpected.append("-n")
        raise ParseError(109, "invalid command-line arguments", f"The following arguments were not expected: {' '.join(unexpected)}")

    return opts


def parse_cutoff(value: str, name: str) -> datetime:
    parsed = parse_timestamp(value)
    if parsed is None:
        raise RuntimeCliError(1, [f"  error: invalid '{name}' time “{value}”", " reason: Unrecognized input"])
    return parsed


def execute_commands(runtime: RuntimeContext, state: State) -> None:
    commands: list[tuple[str, str, int]] = []

    for index, command in enumerate(runtime.opts.command_options, start=1):
        commands.append(("option", command, index))

    option_count = len(commands)
    for offset, command_file in enumerate(runtime.opts.command_files, start=1):
        commands.extend(read_script_command_file(command_file, option_count + offset))

    for source_kind, command, index in commands:
        if not command:
            continue
        prefix = command[0]
        if prefix not in ":;|":
            sys.stderr.write(INVALID_C_HELP.format(cmd=command))
            raise RuntimeCliError(105, [])

        if prefix == ":":
            run_builtin_command(state, command[1:].strip(), index)
        elif prefix == ";":
            execute_sql_command(state, command[1:], index)
        elif prefix == "|":
            execute_script(state, command[1:], index)


def read_script_command_file(path: str, index: int) -> list[tuple[str, str, int]]:
    if path == "-":
        text = sys.stdin.read()
    else:
        target = Path(path)
        if not target.exists():
            sys.stderr.write(
                f"  error: unknown script -- {path} -- file not found\n"
                f" --> command-option:{index}\n"
                f" | |{path:<35}\n"
            )
            return []
        text = target.read_text(encoding="utf-8")

    commands = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        commands.append(("script", stripped, index))
    return commands


def execute_script(state: State, script_ref: str, index: int) -> None:
    commands = read_script_command_file(script_ref, index)
    for _, command, inner_index in commands:
        prefix = command[0]
        if prefix == ":":
            run_builtin_command(state, command[1:].strip(), inner_index)
        elif prefix == ";":
            execute_sql_command(state, command[1:], inner_index)
        elif prefix == "|":
            execute_script(state, command[1:], inner_index)
        else:
            sys.stderr.write(INVALID_C_HELP.format(cmd=command))
            state.had_command_error = True


def run_builtin_command(state: State, command: str, index: int) -> None:
    parts = shlex.split(command)
    if not parts:
        return

    name = parts[0]
    args = parts[1:]

    if name == "filter-in":
        pattern = args[0] if args else ""
        state.visible_entries = [entry for entry in state.visible_entries if matches_filter(entry.raw_line, pattern)]
        for entry in state.visible_entries:
            entry.log_filters = "[1]"
        state.current_index = 0
        state.last_query = None
        return

    if name == "filter-out":
        pattern = args[0] if args else ""
        state.visible_entries = [entry for entry in state.visible_entries if not matches_filter(entry.raw_line, pattern)]
        state.current_index = 0
        state.last_query = None
        return

    if name == "goto":
        if not state.visible_entries or not args:
            return
        target = args[0]
        if re.fullmatch(r"-?\d+", target):
            index_value = max(0, min(int(target), len(state.visible_entries) - 1))
            state.current_index = index_value
            return
        target_time = parse_timestamp(target)
        if target_time is None:
            return
        for idx, entry in enumerate(state.visible_entries):
            if entry.log_time >= target_time:
                state.current_index = idx
                return
        state.current_index = len(state.visible_entries) - 1
        return

    if name in {
        "highlight",
        "highlight-field",
        "partition-name",
        "config",
        "save-session",
        "load-session",
    }:
        return

    if name == "write-csv-to":
        state.explicit_output = write_csv_output(state)
        return

    if name == "write-json-to":
        state.explicit_output = write_json_output(state)
        return

    if name == "write-jsonlines-to":
        state.explicit_output = write_jsonlines_output(state)
        return

    if name == "write-table-to":
        if state.last_query is not None:
            state.explicit_output = format_table(state.last_query)
        else:
            state.explicit_output = render_log_lines(state.visible_entries)
        return

    if name == "write-to":
        sys.stderr.write(WRITE_TO_HELP.format(index=index))
        state.had_command_error = True
        return

    sys.stderr.write(f"  error: unknown command: “{name}”\n")
    state.had_command_error = True


def execute_sql_command(state: State, sql: str, index: int) -> None:
    sql = sql.strip()
    special = normalize_sql(sql)
    if special == "select * from logline":
        state.last_query = query_logline_star(state)
        return

    db = sqlite3.connect(":memory:")
    db.row_factory = sqlite3.Row
    load_sqlite_schema(db, state)

    try:
        cursor = db.execute(sql)
        columns = [desc[0] for desc in cursor.description or []]
        rows = [tuple(row) for row in cursor.fetchall()] if columns else []
        state.last_query = QueryResult(columns=columns, rows=rows)
    except sqlite3.Error as exc:
        sys.stderr.write(
            f"  error: failed to compile SQL statement\n"
            f" reason: {exc}\n"
            f" --> command-option:{index}\n"
            f" | {sql:<35}\n"
        )
        state.had_command_error = True
    finally:
        db.close()


def load_sqlite_schema(db: sqlite3.Connection, state: State) -> None:
    db.execute(
        """
        CREATE TABLE all_logs (
            log_line INTEGER,
            log_time TEXT,
            log_level TEXT,
            log_msg_format TEXT,
            log_msg_values TEXT,
            log_msg_src TEXT,
            log_stack_trace TEXT,
            log_part TEXT,
            log_idle_msecs INTEGER,
            log_mark INTEGER,
            log_comment TEXT,
            log_tags TEXT,
            log_annotations TEXT,
            log_filters TEXT,
            log_text TEXT,
            log_body TEXT,
            log_path TEXT,
            log_actual_time TEXT,
            log_time_msecs INTEGER,
            ex_procname TEXT,
            ex_duration INTEGER
        )
        """
    )

    db.execute(
        """
        CREATE TABLE logline (
            log_line INTEGER,
            log_time TEXT,
            log_level TEXT,
            log_part TEXT,
            log_idle_msecs INTEGER,
            log_mark INTEGER,
            log_comment TEXT,
            log_tags TEXT,
            log_annotations TEXT,

            log_annotations TEXT,
            log_filters TEXT,
            log_text TEXT,
            log_body TEXT
        )
        """
    )

    db.execute("CREATE TABLE environ (name TEXT, value TEXT)")

    for entry in state.visible_entries:
        epoch_msecs = int(entry.log_time.replace(tzinfo=timezone.utc).timestamp() * 1000)
        db.execute(
            """
            INSERT INTO all_logs VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                entry.log_line,
                format_sql_time(entry.log_time),
                entry.level,
                entry.body,
                "null",
                None,
                None,
                None,
                entry.log_idle_msecs,
                0,
                None,
                None,
                None,
                entry.log_filters,
                entry.raw_line,
                entry.body,
                entry.path,
                format_sql_time(entry.log_time),
                epoch_msecs,
                None,
                None,
            ),
        )

    if state.visible_entries:
        entry = state.visible_entries[min(state.current_index, len(state.visible_entries) - 1)]
        db.execute(
            """
            INSERT INTO logline VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                state.current_index,
                format_sql_time(entry.log_time),
                entry.level,
                None,
                0 if state.current_index == 0 else entry.log_idle_msecs,
                0,
                None,
                None,
                None,
                entry.log_filters,
                entry.raw_line,
                entry.body,
            ),
        )
    db.commit()


def query_logline_star(state: State) -> QueryResult:
    columns = [
        "log_line",
        "log_time",
        "log_level",
        "log_part",
        "log_idle_msecs",
        "log_mark",
        "log_comment",
        "log_tags",
        "log_annotations",
        "log_filters",
    ]
    if not state.visible_entries:
        return QueryResult(columns=columns, rows=[])
    entry = state.visible_entries[min(state.current_index, len(state.visible_entries) - 1)]
    row = (
        state.current_index,
        format_sql_time(entry.log_time),
        entry.level,
        None,
        0 if state.current_index == 0 else entry.log_idle_msecs,
        0,
        None,
        None,
        None,
        entry.log_filters,
    )
    return QueryResult(columns=columns, rows=[row])


def normalize_sql(sql: str) -> str:
    return " ".join(sql.lower().split())


def write_csv_output(state: State) -> str:
    rows, columns = rows_and_columns_for_export(state)
    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(columns)
    for row in rows:
        writer.writerow(["" if value is None else value for value in row])
    return output.getvalue()


def write_json_output(state: State) -> str:
    rows, columns = rows_and_columns_for_export(state)
    payload = [dict(zip(columns, row)) for row in rows]
    return json.dumps(payload, indent=4) + ("\n" if payload else "[]\n")


def write_jsonlines_output(state: State) -> str:
    rows, columns = rows_and_columns_for_export(state)
    lines = [json.dumps(dict(zip(columns, row))) for row in rows]
    return ("\n".join(lines) + "\n") if lines else ""


def rows_and_columns_for_export(state: State) -> tuple[list[tuple[object, ...]], list[str]]:
    if state.last_query is not None:
        return state.last_query.rows, state.last_query.columns
    columns = ["log_text"]
    rows = [(entry.raw_line,) for entry in state.visible_entries]
    return rows, columns


def format_table(result: QueryResult) -> str:
    if not result.columns:
        return ""

    formatted_rows = [tuple(format_value(value) for value in row) for row in result.rows]
    widths = [len(column) for column in result.columns]
    numeric = [all(isinstance(row[idx], (int, float)) and not isinstance(row[idx], bool) for row in result.rows) for idx in range(len(result.columns))]

    for row in formatted_rows:
        for idx, value in enumerate(row):
            widths[idx] = max(widths[idx], len(value))

    def format_cell(value: str, idx: int, *, header: bool = False) -> str:
        width = widths[idx]
        if header:
            return f" {value:<{width}} "
        if numeric[idx]:
            return f" {value:>{width}} "
        return f" {value:<{width}} "

    lines = []
    lines.append("".join(format_cell(column, idx, header=True) for idx, column in enumerate(result.columns)).rstrip() + " \n")
    for row in formatted_rows:
        lines.append("".join(format_cell(value, idx) for idx, value in enumerate(row)).rstrip() + " \n")
    return "".join(lines)


def format_value(value: object) -> str:
    if value is None:
        return "<NULL>"
    if isinstance(value, str):
        return value
    return str(value)


def render_log_lines(entries: Iterable[Entry]) -> str:
    lines = [entry.raw_line for entry in entries]
    return ("\n".join(lines) + "\n") if lines else ""


def render_plain_lines(lines: Iterable[PlainLine]) -> str:
    values = [line.raw_line for line in lines]
    return ("\n".join(values) + "\n") if values else ""


def parse_line(line: str) -> tuple[datetime, str] | None:
    match = ISO_LINE_RE.match(line)
    if match:
        stamp = parse_timestamp(match.group("stamp"))
        if stamp is not None:
            return stamp, match.group("body")

    match = SYSLOG_RE.match(line)
    if match:
        stamp = parse_syslog_timestamp(match.group("stamp"))
        if stamp is not None:
            return stamp, match.group("body")
    return None


def parse_timestamp(value: str) -> datetime | None:
    normalized = value
    if normalized.endswith("Z"):
        normalized = normalized[:-1] + "+00:00"
    if re.search(r"[+-]\d{4}$", normalized):
        normalized = normalized[:-5] + normalized[-5:-2] + ":" + normalized[-2:]

    for candidate in (
        normalized,
        normalized.replace("T", " "),
    ):
        try:
            parsed = datetime.fromisoformat(candidate)
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            return parsed
        except ValueError:
            continue
    return None


def parse_syslog_timestamp(value: str) -> datetime | None:
    year = datetime.now().year
    for fmt in ("%b %d %H:%M:%S", "%b  %d %H:%M:%S"):
        try:
            parsed = datetime.strptime(f"{year} {value}", f"%Y {fmt}")
            return parsed
        except ValueError:
            continue
    return None


def ensure_timestamp(line: str) -> str:
    if parse_line(line) is not None:
        return line
    now = datetime.now(timezone.utc).astimezone()
    return f"{now.strftime('%Y-%m-%dT%H:%M:%S.%f%z')} {line}"


def detect_level(body: str) -> str:
    lowered = body.lower()
    if "error" in lowered:
        return "error"
    if "warning" in lowered or "warn" in lowered:
        return "warning"
    if "info" in lowered:
        return "info"
    if "debug" in lowered:
        return "debug"
    return "unknown"


def matches_filter(line: str, pattern: str) -> bool:
    if not pattern:
        return True
    try:
        return re.search(pattern, line) is not None
    except re.error:
        return pattern in line


def format_sql_time(value: datetime) -> str:
    return value.strftime("%Y-%m-%d %H:%M:%S.%f")


def read_text_file(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix == ".gz":
        with gzip.open(path, "rt", encoding="utf-8", errors="replace") as fh:
            return fh.read()
    if suffix == ".bz2":
        with bz2.open(path, "rt", encoding="utf-8", errors="replace") as fh:
            return fh.read()
    if suffix in {".xz", ".lzma"}:
        with lzma.open(path, "rt", encoding="utf-8", errors="replace") as fh:
            return fh.read()
    return path.read_text(encoding="utf-8", errors="replace")


def load_internal_help() -> str:
